using System.Net.Http.Headers;using System.Net.Http.Json;using System.Text.Json;using TaskPanel.Api.Models;
namespace TaskPanel.Api.Services;
public class SupabaseAuthService(IHttpClientFactory clients,IConfiguration config){
  string Url=>config["Supabase:Url"]!.TrimEnd('/');string Key=>config["Supabase:PublishableKey"]!;
  public async Task<JsonElement?> LoginAsync(LoginRequest request){var client=clients.CreateClient();using var message=new HttpRequestMessage(HttpMethod.Post,$"{Url}/auth/v1/token?grant_type=password");message.Headers.Add("apikey",Key);message.Content=JsonContent.Create(new{email=request.Email,password=request.Password});var response=await client.SendAsync(message);return response.IsSuccessStatusCode?await response.Content.ReadFromJsonAsync<JsonElement>():null;}
  public async Task<CurrentUser?> ValidateAsync(string token){var client=clients.CreateClient();using var message=new HttpRequestMessage(HttpMethod.Get,$"{Url}/auth/v1/user");message.Headers.Add("apikey",Key);message.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);var response=await client.SendAsync(message);if(!response.IsSuccessStatusCode)return null;var json=await response.Content.ReadFromJsonAsync<JsonElement>();var metadata=json.GetProperty("user_metadata");var appMetadata=json.GetProperty("app_metadata");var email=json.GetProperty("email").GetString()!;var name=metadata.TryGetProperty("full_name",out var n)?n.GetString()??email:email;var role=appMetadata.TryGetProperty("app_role",out var r)?r.GetString()??"employee":"employee";return new(json.GetProperty("id").GetGuid(),email,name,role,token);}
}
